// Bora Radar: npm run build prepara o aplicativo. Não inclui chaves ou senhas.
import {gunzipSync} from 'node:zlib';
import {mkdirSync,writeFileSync} from 'node:fs';
import {dirname,resolve,sep} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
const root=dirname(fileURLToPath(import.meta.url));
const manifest=JSON.parse(gunzipSync(Buffer.from('','base64')).toString('utf8'));
for(const f of manifest){const target=resolve(root,f.path);if(!target.startsWith(root+sep)||!(/^(src\/|public\/|migrations\/|scripts\/core\.test\.mjs$|\.gitignore$)/.test(f.path)))throw Error('Caminho inválido');const data=Buffer.from(f.data,'base64');if(createHash('sha256').update(data).digest('hex')!==f.sha256)throw Error('Arquivo corrompido');mkdirSync(dirname(target),{recursive:true});writeFileSync(target,data)}
console.log('Bora Radar preparado. Configuração e secrets preservados.');
